-- ───────── Offerings (offer_code = SUBJECT-TERMID-SECTION, same format the API generates) ─────────

-- ───────── Enrollments ─────────

UPDATE offerings o SET current_slots = (SELECT COUNT(*) FROM enrollments e WHERE e.offering_id = o.id AND e.request_status = 'ENROLLED');

-- ───────── Grades (entered_by = the professor of the offering) and their history ─────────
DELETE gh FROM grade_history gh JOIN grades g ON g.id = gh.grade_id JOIN enrollments e ON e.id = g.enrollment_id JOIN students st ON st.id = e.student_id WHERE st.student_id_no IN ('2025-0001','2025-0002','2025-0004','2025-0005','2025-0006','2025-0007','2025-0008','2025-0009','2025-0010','2025-0011','2025-0012');

